 static class Match {Store.Book b;double score;boolean exact;Match(Store.Book book,double s,boolean e){b=book;score=s;exact=e;}}
 ArrayList<Match> matches(){ArrayList<Match> items=new ArrayList<>();for(Store.Book b:store.snapshot()){if(!category.isEmpty()&&!b.category.equals(category))continue;double score=SearchCore.score(query,b.title,b.author,b.keywords);if(score>0)items.add(new Match(b,score,SearchCore.exact(query,b.title)));}items.sort((a,b)->{int d=Double.compare(b.score,a.score);return d!=0?d:a.b.title.compareToIgnoreCase(b.b.title);});return items;}
