 void refresh(boolean feedback){if(indexing){if(feedback)toast("El catálogo ya se está actualizando");return;}indexing=true;lastScan=System.currentTimeMillis();if(feedback)toast("Actualizando catálogo…");io.execute(()->{String report;try{report=store.scan();}catch(Exception e){report="No se pudo actualizar el catálogo. Revisa los permisos y el espacio disponible.";}final String r=report;ui.post(()->{indexing=false;coverCache.evictAll();if(isDestroyed())return;if(feedback)message("Catálogo",r);if(screen.equals("admin")&&adminAuthorized)admin();else if(screen.equals("results"))results();});});}
