 void chooseFolderCategory(){ArrayList<Store.Category> cats=store.cats();String[] names=new String[cats.size()+1];for(int i=0;i<cats.size();i++)names[i]=cats.get(i).name;names[cats.size()]="Sin categoría";new AlertDialog.Builder(this).setTitle("Categoría inicial para los PDF nuevos").setItems(names,(d,w)->{pickCategory=w<cats.size()?cats.get(w).id:"";Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(intent,11);}).show();}
