 void adminBooks(String assignment){if(!adminAuthorized)return;begin("adminBooks");LinearLayout top=row();top.addView(label(assignment.isEmpty()?"Archivos del catálogo":"Asignar a "+store.categoryName(assignment),24,INK),new LinearLayout.LayoutParams(0,-2,1));top.addView(button("Administración",v->admin(),false));root.addView(top);EditText filter=new EditText(this);filter.setHint("Filtrar archivos por título o autor");filter.setSingleLine(true);filter.setTextSize(22);LargeKeyboard.bind(this,filter,null,false);root.addView(filter);ListView list=new ListView(this);root.addView(list,new LinearLayout.LayoutParams(-1,0,1));ArrayList<Store.Book> all=store.snapshot(),shown=new ArrayList<>(all);BaseAdapter adapter=new BaseAdapter(){public int getCount(){return shown.size();}public Object getItem(int i){return shown.get(i);}public long getItemId(int i){return i;}public View getView(int i,View old,android.view.ViewGroup parent){Store.Book b=shown.get(i);LinearLayout r=row();TextView t=label(b.title+"\n"+(b.author.isEmpty()?"Autor no indicado":b.author)+" · "+store.categoryName(b.category),20,INK);r.addView(t,new LinearLayout.LayoutParams(0,-2,1));r.addView(button(assignment.isEmpty()?"Editar":b.category.equals(assignment)?"Asignado":"Asignar",v->{if(!assignment.isEmpty()){b.category=assignment;store.put(b);notifyDataSetChanged();}else editBook(b,()->adminBooks(assignment));},!assignment.isEmpty()&&!b.category.equals(assignment)));return r;}};list.setAdapter(adapter);filter.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){shown.clear();String q=SearchCore.norm(s.toString());for(Store.Book b:all)if(SearchCore.norm(b.title+" "+b.author).contains(q))shown.add(b);adapter.notifyDataSetChanged();}public void afterTextChanged(Editable e){}});}
 void editBook(Store.Book b,Runnable done){ScrollView sc=new ScrollView(this);LinearLayout body=column();sc.addView(body);EditText title=new EditText(this),author=new EditText(this),keywords=new EditText(this);title.setText(b.title);title.setHint("Título");author.setText(b.author);author.setHint("Autor");keywords.setText(b.keywords);keywords.setHint("Palabras clave");for(EditText e:new EditText[]{title,author,keywords}){e.setTextSize(20);LargeKeyboard.bind(this,e,null,false);body.addView(e);}ArrayList<Store.Category> cats=store.cats();String[] names=new String[cats.size()+1];int current=cats.size();for(int i=0;i<cats.size();i++){names[i]=cats.get(i).name;if(cats.get(i).id.equals(b.category))current=i;}names[cats.size()]="Sin categoría";Spinner spin=new Spinner(this);spin.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));spin.setSelection(current);body.addView(spin);body.addView(label("Precios opcionales del libro completo ("+prefs.getString("currency","S/")+")",20,INK));EditText[] prices=new EditText[4];for(int i=0;i<4;i++){body.addView(label(PrintPrices.LABELS[i],17,MUTED));EditText e=new EditText(this);e.setTextSize(20);e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);e.setHint("Opcional: vacío para consultar precio");e.setText(b.prices[i]);LargeKeyboard.bind(this,e,null,true);body.addView(e);prices[i]=e;}AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Editar datos y precios").setView(sc).setPositiveButton("Guardar",null).setNegativeButton("Cancelar",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{if(title.getText().toString().trim().isEmpty()){title.setError("Escribe un título");return;}String[] values=new String[4];for(int i=0;i<4;i++)try{values[i]=PrintPrices.valid(prices[i].getText().toString());}catch(Exception ex){prices[i].setError(ex.getMessage());return;}b.title=title.getText().toString().trim();b.author=author.getText().toString().trim();b.keywords=keywords.getText().toString().trim();int i=spin.getSelectedItemPosition();b.category=i<cats.size()?cats.get(i).id:"";b.prices=values;b.edited=true;store.put(b);dialog.dismiss();done.run();}));dialog.show();}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);touch();if(!adminAuthorized||result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(request==11){try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);synchronized(store){boolean found=false;for(Store.Folder f:store.folders)if(f.uri.equals(uri.toString())){f.category=pickCategory;found=true;}if(!found)store.folders.add(new Store.Folder(uri.toString(),pickCategory));store.save();}admin();refresh(true);}catch(Exception e){message("No se concedió acceso","Selecciona una carpeta de documentos. Android no permite acceder a algunas carpetas del sistema.");}}else if(request==12){String target=pickState;int token=generation;toast("Cargando PNG…");io.execute(()->{try{byte[] sig=new byte[8];try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null||in.read(sig)!=8||!Arrays.equals(sig,new byte[]{(byte)137,80,78,71,13,10,26,10}))throw new IOException("El archivo debe ser PNG");}BitmapFactory.Options opts=new BitmapFactory.Options();opts.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(uri)){BitmapFactory.decodeStream(in,null,opts);}if(opts.outWidth<1||opts.outHeight<1||opts.outWidth>20000||opts.outHeight>20000)throw new IOException("Imagen demasiado grande o dañada");opts.inJustDecodeBounds=false;opts.inSampleSize=Math.max(1,Math.max(opts.outWidth,opts.outHeight)/1024);Bitmap img;try(InputStream in=getContentResolver().openInputStream(uri)){img=BitmapFactory.decodeStream(in,null,opts);}if(img==null)throw new IOException("PNG dañado");File dir=new File(getFilesDir(),"wolves");dir.mkdirs();File file=new File(dir,target+".png"),temp=new File(dir,target+".tmp");try(OutputStream out=new FileOutputStream(temp)){img.compress(Bitmap.CompressFormat.PNG,100,out);}img.recycle();if(!temp.renameTo(file))throw new IOException("No se pudo guardar");prefs.edit().putString("wolf_"+target,file.toString()).commit();ui.post(()->{if(!isDestroyed()&&adminAuthorized&&generation==token){toast("Lobito actualizado");admin();}});}catch(Exception|OutOfMemoryError e){ui.post(()->{if(!isDestroyed())message("No se pudo cargar la imagen","Usa un PNG válido y revisa el espacio disponible.");});}});}}
 boolean online(){ConnectivityManager cm=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);Network n=cm.getActiveNetwork();NetworkCapabilities c=cm.getNetworkCapabilities(n);return c!=null&&c.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET);}
 void internet(){if(search!=null)query=search.getText().toString().trim();hideKeyboard();if(query.isEmpty()){toast("Escribe lo que quieres buscar en Google");return;}if(!online()){message("Sin conexión","La biblioteca y los PDF locales siguen disponibles.");return;}if(browser!=null)browser.close();begin("browser");root.setPadding(0,0,0,0);browser=new GoogleBrowser(this,query);root.addView(browser,new LinearLayout.LayoutParams(-1,-1));}
 void showBrowser(){if(browser==null){results();return;}begin("browser");root.setPadding(0,0,0,0);android.view.ViewParent parent=browser.getParent();if(parent instanceof android.view.ViewGroup)((android.view.ViewGroup)parent).removeView(browser);browser.compact(false);root.addView(browser,new LinearLayout.LayoutParams(-1,-1));}
 void readerBack(){results();}
 void downloadWebPdf(String url,String title,String ua,String cookie,String referer,Runnable reset){for(Store.Book existing:store.snapshot())if(existing.source.equals(url)&&existing.uri.startsWith("file:")&&new File(Uri.parse(existing.uri).getPath()).exists()){reset.run();openBook(existing,true);return;}if(!online()){reset.run();message("Sin conexión","Conecta la tablet para abrir este PDF.");return;}int token=generation;AtomicBoolean cancel=new AtomicBoolean(false);cancelDownload=cancel;LinearLayout body=column();TextView status=label("Abriendo PDF del enlace…",18,INK);ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setIndeterminate(true);body.addView(status);body.addView(bar);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Descargando PDF").setView(body).setNegativeButton("Cancelar",(d,w)->cancel.set(true)).setCancelable(false).create();downloadDialog=dialog;dialog.show();io.execute(()->{File dir=new File(getFilesDir(),"downloads");dir.mkdirs();File temp=new File(dir,UUID.randomUUID()+".part");try{WebPdf.download(url,ua,cookie,referer,temp,new WebPdf.Progress(){public boolean cancelled(){return cancel.get()||token!=generation||isDestroyed();}public void update(long bytes,long total){ui.post(()->{if(!dialog.isShowing())return;status.setText(String.format(Locale.ROOT,"%.1f MB%s",bytes/1048576.0,total>0?String.format(Locale.ROOT," de %.1f MB",total/1048576.0):""));if(total>0){bar.setIndeterminate(false);bar.setProgress((int)(100*bytes/total));}touch();});}});if(cancel.get()||token!=generation)throw new IOException("Descarga cancelada");try(PdfSession check=new PdfSession(this,Uri.fromFile(temp).toString())){check.renderFit(0,48,64).recycle();}String name=title.replaceFirst("(?i)\\.pdf$","");String[] metadata=PdfMetadata.read(this,Uri.fromFile(temp).toString());if(!metadata[0].isEmpty())name=metadata[0];File dest=new File(dir,UUID.randomUUID()+".pdf");if(!temp.renameTo(dest))throw new IOException("No se pudo guardar el archivo. Revisa el espacio disponible.");Store.Book b=new Store.Book(Uri.fromFile(dest).toString(),name);b.author=metadata[1];b.keywords=metadata[2];b.source=url;b.license="Verificar licencia en la fuente";b.category="";for(Store.Category c:store.cats())if(c.id.equals("books"))b.category="books";store.put(b);ui.post(()->{dialog.dismiss();if(downloadDialog==dialog)downloadDialog=null;reset.run();if(token==generation&&!isDestroyed())openBook(b,true);});}catch(Exception|OutOfMemoryError ex){temp.delete();ui.post(()->{dialog.dismiss();if(downloadDialog==dialog)downloadDialog=null;reset.run();if(token!=generation||isDestroyed()||cancel.get())return;message("No se pudo abrir el PDF",ex.getMessage()==null?"El archivo no es compatible o no hay memoria suficiente.":ex.getMessage());});}});}
 void finishVisit(){if(screen.equals("images")&&images!=null){images.finish();return;}if(idleDialog!=null){idleDialog.dismiss();idleDialog=null;}touch();new AlertDialog.Builder(this).setTitle("Finalizar visita").setItems(new String[]{"Enviar al WhatsApp para impresión","Luego lo imprimiré, gracias"},(d,w)->{if(w==1)endVisit();else if(activeBook==null)message("Abre un libro primero","Busca y abre el PDF que quieres imprimir. Después podrás ver sus precios y enviarlo por WhatsApp.");else printOptions(activeBook);}).setNegativeButton("Seguir leyendo",null).show();}
 void printOptions(Store.Book b){String currency=prefs.getString("currency","S/");int first=0;String[] options=new String[4];for(int i=0;i<4;i++){options[i]=PrintPrices.LABELS[i]+"  ·  "+PrintPrices.display(b.prices[i],currency);if(!b.prices[i].isEmpty()&&first<0)first=i;}final int[] chosen={first};LinearLayout body=column();body.addView(label(b.title+"\nPrecio del libro completo, sin multiplicar por páginas.",20,INK));RadioGroup group=new RadioGroup(this);for(int i=0;i<4;i++){final int index=i;RadioButton radio=new RadioButton(this);radio.setId(100+i);radio.setText(options[i]);radio.setTextSize(21);radio.setMinHeight(dp(64));radio.setEnabled(true);group.addView(radio);radio.setOnClickListener(v->chosen[0]=index);}if(first>=0)group.check(100+first);body.addView(group);body.addView(label("Si una opción no tiene precio, puedes enviar el PDF y consultar el importe por WhatsApp.",17,MUTED));body.addView(label("Se adjuntará el PDF a WhatsApp para el número +51 952 628 844. Confirma el envío en WhatsApp.",16,MUTED));AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Elige formato y precio").setView(body).setPositiveButton("Enviar PDF a WhatsApp",(d,w)->{if(chosen[0]>=0)shareToWhatsApp(b,chosen[0]);}).setNegativeButton("Volver",null).create();final boolean enabled=first>=0;dialog.setOnShowListener(d->dialog.getButton(-1).setEnabled(enabled));dialog.show();}
 void shareToWhatsApp(Store.Book b,int format){String target=null;for(String pkg:new String[]{"com.whatsapp","com.whatsapp.w4b"})try{getPackageManager().getPackageInfo(pkg,0);target=pkg;break;}catch(Exception ignored){}if(target==null){message("WhatsApp no está instalado","Para enviar el archivo, instala WhatsApp o WhatsApp Business en esta tablet y configura esa aplicación. Grifplotlibros no solicita cuentas ni credenciales.");return;}final String pkg=target,currency=prefs.getString("currency","S/"),price=b.prices[format];int token=generation;AtomicBoolean cancelled=new AtomicBoolean(false);LinearLayout body=column();TextView status=label("Preparando el PDF para WhatsApp…",18,INK);body.addView(status);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Adjuntar libro").setView(body).setNegativeButton("Cancelar",(d,w)->cancelled.set(true)).setCancelable(false).create();dialog.show();io.execute(()->{File out=null;try{File dir=new File(getCacheDir(),"shares");dir.mkdirs();File[] older=dir.listFiles();if(older!=null)for(File f:older)if(System.currentTimeMillis()-f.lastModified()>86400000L)f.delete();String name=b.title.replaceAll("[^a-zA-Z0-9_-]","_");if(name.length()>45)name=name.substring(0,45);out=new File(dir,name+"-"+UUID.randomUUID()+".pdf");try(InputStream in=getContentResolver().openInputStream(Uri.parse(b.uri));OutputStream os=new FileOutputStream(out)){if(in==null)throw new IOException("No se pudo leer el PDF");byte[] buf=new byte[65536];int n;long copied=0,last=0;while((n=in.read(buf))!=-1){if(cancelled.get()||token!=generation)throw new IOException("Cancelado");copied+=n;if(copied>1024L*1024*1024)throw new IOException("El PDF supera 1 GB");os.write(buf,0,n);if(System.currentTimeMillis()-last>300){final long count=copied;ui.post(()->{status.setText(String.format(Locale.ROOT,"Preparando %.1f MB…",count/1048576.0));touch();});last=System.currentTimeMillis();}}}if(cancelled.get()||token!=generation)throw new IOException("Cancelado");Uri uri=Uri.parse("content://"+getPackageName()+".libros.share/share/"+out.getName());ui.post(()->{dialog.dismiss();if(token!=generation||isDestroyed())return;Intent send=new Intent(Intent.ACTION_SEND);send.setType("application/pdf");send.setPackage(pkg);send.putExtra("jid","51952628844@s.whatsapp.net");send.putExtra(Intent.EXTRA_STREAM,uri);send.putExtra(Intent.EXTRA_TEXT,"Solicitud de impresión\nLibro: "+b.title+"\nFormato: "+PrintPrices.LABELS[format]+"\nPrecio del libro completo: "+PrintPrices.display(price,currency)+"\nDestino: +51 952 628 844");send.setClipData(ClipData.newRawUri("PDF del libro",uri));send.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{grantUriPermission(pkg,uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(send);endVisit();}catch(Exception ex){message("No se pudo abrir WhatsApp","Revisa que WhatsApp esté disponible para recibir archivos PDF en esta tablet.");}});}catch(Exception ex){if(out!=null)out.delete();ui.post(()->{dialog.dismiss();if(!cancelled.get()&&token==generation&&!isDestroyed())message("No se pudo adjuntar el PDF","Revisa que el archivo siga disponible y que haya espacio libre.");});}});}
